/* R3.2 deterministic, browser-side C2000 code generator. */
(function (root, factory) {
  const json = root.DeterministicJSON ||
    (typeof require === 'function' ? require('./deterministic_json.js') : null);
  const checker = root.ConstraintChecker ||
    (typeof require === 'function' ? require('./constraint_checker.js') : null);
  const api = factory(json, checker);
  if (typeof module === 'object' && module.exports) module.exports = api;
  root.Codegen = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function (JSONCore, Checker) {
  'use strict';

  const MAX_SYSCLK_HZ = 60000000;
  const INTOSC1_HZ = 10000000;
  const HEADER = [
    '// AUTO-GENERATED BY C2000 CONFIG STUDIO R3.2 STATIC',
    '// LOGIC TEST ONLY',
    '// NOT APPROVED FOR POWER-STAGE ENABLE',
    '// Review every register write against the TI device documentation.',
    '',
  ].join('\n');

  const ADC_CHANNELS = Object.fromEntries(
    Array.from({ length: 8 }, (_, index) => [`ADCINA${index}`, index])
      .concat(Array.from({ length: 8 }, (_, index) => [`ADCINB${index}`, 8 + index])),
  );
  const ADC_TRIGGERS = {
    SOFTWARE: 0,
    CPUTIMER0: 1,
    CPUTIMER1: 2,
    CPUTIMER2: 3,
    EPWM1_SOCA: 5,
    EPWM1_SOCB: 6,
    EPWM2_SOCA: 7,
    EPWM2_SOCB: 8,
    EPWM3_SOCA: 9,
    EPWM3_SOCB: 10,
    EPWM4_SOCA: 11,
    EPWM4_SOCB: 12,
    EPWM5_SOCA: 13,
    EPWM5_SOCB: 14,
    EPWM6_SOCA: 15,
    EPWM6_SOCB: 16,
    EPWM7_SOCA: 17,
    EPWM7_SOCB: 18,
  };

  const PROFILES = {
    gpio_output: { direction: 'output', pullup: 'disable' },
    gpio_input: { direction: 'input', pullup: 'disable', qualification: 'sync' },
    epwm_output: { direction: 'output', pullup: 'disable' },
    trip_async_input: { direction: 'input', pullup: 'disable', qualification: 'async' },
    i2c_scla: { direction: 'input', pullup: 'enable', qualification: 'async' },
    i2c_sdaa: { direction: 'input', pullup: 'enable', qualification: 'async' },
    spi_input: { direction: 'input', pullup: 'disable', qualification: 'sync' },
    spi_output: { direction: 'output', pullup: 'disable' },
    sci_rx: { direction: 'input', pullup: 'enable', qualification: 'async' },
    sci_tx: { direction: 'output', pullup: 'disable' },
    eqep_input: { direction: 'input', pullup: 'enable', qualification: 'sync' },
  };

  function lineFile(lines) {
    return lines.join('\n') + '\n';
  }

  function configuredPins(config) {
    return Object.entries(config.pins || {}).map(([key, value]) => ({
      physical_pin: Number(value.physical_pin ?? key),
      ...value,
    })).sort((a, b) => a.physical_pin - b.physical_pin);
  }

  function pdef(pinmux, physicalPin) {
    return pinmux?.pins?.[String(Number(physicalPin))] || null;
  }

  function optionFor(pinmux, pin) {
    const def = pdef(pinmux, pin.physical_pin);
    return (def?.mux_options || []).find(option =>
      Number(option.mux) === Number(pin.mux) &&
      String(option.function).toUpperCase() === String(pin.function).toUpperCase(),
    ) || null;
  }

  function inferredProfile(pin, option) {
    if (pin.generator_profile && PROFILES[pin.generator_profile]) {
      return [pin.generator_profile, PROFILES[pin.generator_profile]];
    }
    if (option?.generator_profile && PROFILES[option.generator_profile]) {
      return [option.generator_profile, PROFILES[option.generator_profile]];
    }
    const fn = String(pin.function || '').toUpperCase();
    if (/^GPIO\d+$/.test(fn)) {
      const name = pin.direction === 'input' ? 'gpio_input' : 'gpio_output';
      return [name, PROFILES[name]];
    }
    if (/^TZ[1-3]N$/.test(fn)) return ['trip_async_input', PROFILES.trip_async_input];
    if (fn.includes('SDA')) return ['i2c_sdaa', PROFILES.i2c_sdaa];
    if (fn.includes('SCL')) return ['i2c_scla', PROFILES.i2c_scla];
    if (fn.includes('RX')) return ['sci_rx', PROFILES.sci_rx];
    if (fn.includes('TX')) return ['sci_tx', PROFILES.sci_tx];
    return ['gpio_input', PROFILES.gpio_input];
  }

  function generatePinmux(config, pinmux) {
    const lines = [
      HEADER.trimEnd(),
      '#include "DSP2803x_Device.h"',
      '#include "pinmux_init.h"',
      '',
      'void Generated_PinMux_Init(void)',
      '{',
      '    EALLOW;',
    ];
    let emitted = 0;
    for (const pin of configuredPins(config)) {
      const def = pdef(pinmux, pin.physical_pin);
      if (!def?.configurable) continue;
      const fn = String(pin.function).toUpperCase();
      if (/^EPWM[1-7][AB]$/.test(fn)) {
        lines.push(`    // Pin${pin.physical_pin} ${fn}: applied by PWM init while clamped`);
        continue;
      }
      const option = optionFor(pinmux, pin);
      if (!option) throw new Error(`Pin${pin.physical_pin} ${fn} has no exact MUX option`);
      const [profileName, profile] = inferredProfile(pin, option);
      lines.push(
        `    // Pin${pin.physical_pin} ${def.primary_signal} -> ${option.function}; profile=${profileName}`,
        `    ${def.mux_field} = ${Number(option.mux)}U;`,
      );
      if (Number(option.mux) === 0) {
        const direction = pin.direction || profile.direction || 'output';
        const pullup = pin.pullup || profile.pullup || 'disable';
        if (direction === 'output') {
          const level = pin.initial_level || 'low';
          lines.push(`    ${level === 'high' ? def.set_field : def.clr_field} = 1U;`);
        }
        lines.push(
          `    ${def.dir_field} = ${direction === 'output' ? 1 : 0}U;`,
          `    ${def.pud_field} = ${pullup === 'disable' ? 1 : 0}U;`,
        );
        if (direction === 'input') {
          const qualification = pin.qualification || profile.qualification || 'sync';
          const value = { sync: 0, qual3: 1, qual6: 2, async: 3 }[qualification];
          lines.push(`    ${def.qsel_field} = ${value}U;   // ${qualification}`);
        }
      } else {
        lines.push(`    ${def.pud_field} = ${profile.pullup === 'enable' ? 0 : 1}U;`);
        if (profile.qualification) {
          const value = { sync: 0, qual3: 1, qual6: 2, async: 3 }[profile.qualification];
          lines.push(`    ${def.qsel_field} = ${value}U;   // ${profile.qualification}`);
        }
      }
      emitted += 1;
    }
    if (!emitted) lines.push('    // no non-ePWM pins configured');
    lines.push('    EDIS;', '}');
    return {
      'pinmux_init.c': lineFile(lines),
      'pinmux_init.h': lineFile([
        HEADER.trimEnd(),
        '#ifndef PINMUX_INIT_H',
        '#define PINMUX_INIT_H',
        '',
        'void Generated_PinMux_Init(void);',
        '',
        '#endif',
      ]),
    };
  }

  function generateClock(clock) {
    if (!clock || ['existing', 'keep_existing'].includes(clock.mode)) return {};
    const targetMhz = Number(clock.target_mhz ?? Number(clock.sysclk_hz) / 1e6);
    const div = targetMhz * 2 / (INTOSC1_HZ / 1e6);
    const pllDiv = Math.round(div);
    if (!Number.isFinite(targetMhz) || Math.abs(div - pllDiv) > 1e-9 ||
        pllDiv < 1 || pllDiv > 15 || targetMhz > 60) {
      throw new Error(`illegal system_clock target_mhz=${targetMhz}`);
    }
    return {
      'system_clock_init.c': lineFile([
        HEADER.trimEnd(),
        '#include "DSP2803x_Device.h"',
        '#include "system_clock_init.h"',
        '',
        'Uint16 Generated_SystemClock_Init(void)',
        '{',
        '    Uint32 lock_wait;',
        '    EALLOW;',
        '    SysCtrlRegs.WDCR = 0x0068U;',
        '    SysCtrlRegs.CLKCTL.bit.INTOSC1OFF = 0U;',
        '    SysCtrlRegs.CLKCTL.bit.OSCCLKSRCSEL = 0U;',
        '    if (SysCtrlRegs.PLLSTS.bit.MCLKSTS != 0U) {',
        '        SysCtrlRegs.PLLSTS.bit.MCLKCLR = 1U;',
        '        EDIS;',
        '        return 1U;',
        '    }',
        '    SysCtrlRegs.PLLSTS.bit.DIVSEL = 0U;',
        '    SysCtrlRegs.PLLSTS.bit.MCLKOFF = 1U;',
        '    SysCtrlRegs.PLLLOCKPRD = 0xFFFFU;',
        `    SysCtrlRegs.PLLCR.bit.DIV = ${pllDiv}U;`,
        '    EDIS;',
        '    for (lock_wait = 0UL; lock_wait < 1000000UL; lock_wait++) {',
        '        if (SysCtrlRegs.PLLSTS.bit.PLLLOCKS != 0U) break;',
        '    }',
        '    if (SysCtrlRegs.PLLSTS.bit.PLLLOCKS == 0U) return 2U;',
        '    EALLOW;',
        '    if (SysCtrlRegs.PLLSTS.bit.MCLKSTS != 0U) {',
        '        SysCtrlRegs.PLLSTS.bit.MCLKCLR = 1U;',
        '        EDIS;',
        '        return 3U;',
        '    }',
        '    SysCtrlRegs.PLLSTS.bit.MCLKOFF = 0U;',
        '    SysCtrlRegs.PLLSTS.bit.DIVSEL = 2U;',
        '    if (SysCtrlRegs.PLLSTS.bit.MCLKSTS != 0U) {',
        '        SysCtrlRegs.PLLSTS.bit.MCLKCLR = 1U;',
        '        EDIS;',
        '        return 4U;',
        '    }',
        '    EDIS;',
        '    return 0U;',
        '}',
      ]),
      'system_clock_init.h': lineFile([
        HEADER.trimEnd(),
        '#ifndef SYSTEM_CLOCK_INIT_H',
        '#define SYSTEM_CLOCK_INIT_H',
        '#include "DSP2803x_Device.h"',
        'Uint16 Generated_SystemClock_Init(void);',
        '#endif',
      ]),
    };
  }

  function tbprd(sysclk, frequency, countMode) {
    const value = Math.round(sysclk / ((countMode === 'up_down' ? 2 : 1) * frequency));
    if (!Number.isInteger(value) || value < 1 || value > 0xFFFF) {
      throw new Error(`TBPRD=${value} out of range`);
    }
    return value;
  }

  function aqSettings(profile, countMode, period, duty) {
    if (!(duty > 0 && duty < 1)) throw new Error('PWM duty must be in (0,1)');
    let compare;
    let actions;
    if (countMode === 'up_down') {
      if (profile === 'clear_cau_set_cad') {
        compare = Math.round(period * duty);
        actions = ['AQCTLA.bit.CAU = 1U;', 'AQCTLA.bit.CAD = 2U;'];
      } else {
        compare = Math.round(period * (1 - duty));
        actions = ['AQCTLA.bit.CAU = 2U;', 'AQCTLA.bit.CAD = 1U;'];
      }
    } else if (profile === 'clear_zro_set_cau') {
      compare = Math.round(period * (1 - duty));
      actions = ['AQCTLA.bit.ZRO = 1U;', 'AQCTLA.bit.CAU = 2U;'];
    } else {
      compare = Math.round(period * duty);
      actions = ['AQCTLA.bit.ZRO = 2U;', 'AQCTLA.bit.CAU = 1U;'];
    }
    if (compare <= 0 || compare >= period) throw new Error(`illegal CMPA=${compare}`);
    return { compare, actions };
  }

  function generatePwm(config, pinmux, sysclk) {
    const modules = config.pwm_modules || {};
    if (!Object.keys(modules).length) return {};
    const lines = [
      HEADER.trimEnd(),
      '#include "DSP2803x_Device.h"',
      '#include "pwm_init.h"',
      '',
      'void Generated_Pwm_Init(void)',
      '{',
      '    EALLOW;',
    ];
    const releases = [];
    Object.keys(modules).sort().forEach(name => {
      lines.push(`    SysCtrlRegs.PCLKCR1.bit.${name.toUpperCase()}ENCLK = 1U;`);
    });
    lines.push('    SysCtrlRegs.PCLKCR0.bit.TBCLKSYNC = 0U;', '');

    Object.keys(modules).sort().forEach(rawName => {
      const name = rawName.toUpperCase();
      const match = /^EPWM([1-7])$/.exec(name);
      if (!match) throw new Error(`unsupported PWM module ${name}`);
      const module = modules[rawName];
      const regs = `EPwm${match[1]}Regs`;
      const countMode = module.count_mode || 'up_down';
      const period = tbprd(sysclk, Number(module.frequency_hz), countMode);
      const { compare, actions } = aqSettings(
        module.aq_profile || 'set_cau_clear_cad',
        countMode,
        period,
        Number(module.duty),
      );
      if (module.mode === 'complementary' &&
          (module.pin_a == null || module.pin_b == null)) {
        throw new Error(`${name} complementary requires A/B`);
      }
      const trip = module.trip || {};
      lines.push(
        `    // ${name}: ${module.frequency_hz}Hz, ${countMode}, duty=${module.duty}`,
        `    ${regs}.TZCTL.bit.TZA = 2U;`,
        `    ${regs}.TZCTL.bit.TZB = 2U;`,
      );
      if (trip.enabled) {
        const source = String(trip.source || 'TZ1').toUpperCase().replace(/N$/, '');
        const tm = /^TZ([1-3])$/.exec(source);
        if (!tm) throw new Error(`${name} unsupported trip source ${source}`);
        const kind = trip.mode === 'cycle_by_cycle' ? 'CBC' : 'OSHT';
        lines.push(`    ${regs}.TZSEL.bit.${kind}${tm[1]} = 1U;`);
      }
      lines.push(
        `    ${regs}.AQCSFRC.bit.CSFA = 1U;   // software force low`,
        `    ${regs}.AQCSFRC.bit.CSFB = 1U;`,
        `    ${regs}.TZFRC.bit.OST = 1U;      // hardware clamp before MUX`,
      );
      for (const [channel, physicalPin] of [['A', module.pin_a], ['B', module.pin_b]]) {
        if (physicalPin == null) continue;
        const def = pdef(pinmux, physicalPin);
        const fn = `${name}${channel}`;
        const option = (def?.mux_options || []).find(item =>
          String(item.function).toUpperCase() === fn);
        if (!def || !option) throw new Error(`Pin${physicalPin} does not provide ${fn}`);
        lines.push(
          `    ${def.pud_field} = 1U;`,
          `    ${def.mux_field} = ${Number(option.mux)}U;   // Pin${physicalPin} -> ${fn}`,
        );
      }
      lines.push(
        `    ${regs}.TBCTL.bit.CTRMODE = ${countMode === 'up_down' ? 2 : 0}U;`,
        `    ${regs}.TBCTL.bit.HSPCLKDIV = 0U;`,
        `    ${regs}.TBCTL.bit.CLKDIV = 0U;`,
        `    ${regs}.TBPRD = ${period}U;`,
        `    ${regs}.CMPA.half.CMPA = ${compare}U;`,
      );
      actions.forEach(action => lines.push(`    ${regs}.${action}`));
      if (module.mode === 'complementary') {
        const deadband = module.deadband || {};
        const red = Math.round(Number(deadband.red_ns) * sysclk / 1e9);
        const fed = Math.round(Number(deadband.fed_ns) * sysclk / 1e9);
        if (red < 1 || red > 1023 || fed < 1 || fed > 1023) {
          throw new Error(`${name} deadband ticks out of range`);
        }
        lines.push(
          `    ${regs}.DBCTL.bit.IN_MODE = 0U;`,
          `    ${regs}.DBCTL.bit.OUT_MODE = 3U;`,
          `    ${regs}.DBCTL.bit.POLSEL = 2U;`,
          `    ${regs}.DBRED = ${red}U;`,
          `    ${regs}.DBFED = ${fed}U;`,
        );
      }
      lines.push(`    ${regs}.TBPHS.half.TBPHS = 0U;`, `    ${regs}.TBCTR = 0U;`, '');
      const tripPin = trip.enabled ? pdef(pinmux, trip.pin) : null;
      releases.push({ name, regs, tripPin });
    });
    lines.push(
      '    SysCtrlRegs.PCLKCR0.bit.TBCLKSYNC = 1U;',
      '    EDIS;',
      '}',
      '',
    );

    for (const release of releases) {
      lines.push(
        `Uint16 ${release.name}_ReleaseClamp(void)`,
        '{',
      );
      if (release.tripPin) {
        lines.push(
          `    if (${release.tripPin.dat_field} == 0U) return 1U;   // Trip input still active-low`,
        );
      } else {
        lines.push('    // No hardware Trip input is configured; caller owns the safety decision.');
      }
      lines.push(
        '    EALLOW;',
        `    ${release.regs}.AQCSFRC.bit.CSFA = 1U;`,
        `    ${release.regs}.AQCSFRC.bit.CSFB = 1U;`,
        '    SysCtrlRegs.PCLKCR0.bit.TBCLKSYNC = 0U;',
        `    ${release.regs}.TBCTR = 0U;`,
        `    ${release.regs}.TBPHS.half.TBPHS = 0U;`,
        `    ${release.regs}.TZCLR.bit.INT = 1U;`,
        `    ${release.regs}.TZCLR.bit.CBC = 1U;`,
        `    ${release.regs}.TZCLR.bit.OST = 1U;`,
        '    SysCtrlRegs.PCLKCR0.bit.TBCLKSYNC = 1U;',
        `    ${release.regs}.AQCSFRC.bit.CSFA = 0U;`,
        `    ${release.regs}.AQCSFRC.bit.CSFB = 0U;`,
        '    EDIS;',
        '    return 0U;',
        '}',
        '',
      );
    }
    const headerLines = [
      HEADER.trimEnd(),
      '#ifndef PWM_INIT_H',
      '#define PWM_INIT_H',
      '#include "DSP2803x_Device.h"',
      'void Generated_Pwm_Init(void);',
      ...releases.map(release => `Uint16 ${release.name}_ReleaseClamp(void);`),
      '#endif',
    ];
    return {
      'pwm_init.c': lineFile(lines),
      'pwm_init.h': lineFile(headerLines),
    };
  }

  function generateAdc(adc) {
    if (!adc) return {};
    const soc = Number(adc.soc);
    const acqps = Number(adc.acqps);
    const channel = String(adc.channel || '').toUpperCase();
    const trigger = String(adc.trigger || '').toUpperCase();
    if (!Number.isInteger(soc) || soc < 0 || soc > 15 ||
        !Number.isInteger(acqps) || acqps < 0 || acqps > 63 ||
        ADC_CHANNELS[channel] == null || ADC_TRIGGERS[trigger] == null) {
      throw new Error('ADC setting is not verified');
    }
    return {
      'adc_init.c': lineFile([
        HEADER.trimEnd(),
        '#include "DSP2803x_Device.h"',
        '#include "DSP2803x_Examples.h"',
        '#include "adc_init.h"',
        '',
        'void Generated_Adc_Init(void)',
        '{',
        '    EALLOW;',
        '    SysCtrlRegs.PCLKCR0.bit.ADCENCLK = 1U;',
        '    AdcRegs.ADCCTL1.bit.ADCBGPWD = 1U;',
        '    AdcRegs.ADCCTL1.bit.ADCREFPWD = 1U;',
        '    AdcRegs.ADCCTL1.bit.ADCPWDN = 1U;',
        '    AdcRegs.ADCCTL1.bit.ADCENABLE = 1U;',
        '    EDIS;',
        '    DELAY_US(1000L);',
        '    EALLOW;',
        `    AdcRegs.ADCSOC${soc}CTL.bit.CHSEL = ${ADC_CHANNELS[channel]}U;`,
        `    AdcRegs.ADCSOC${soc}CTL.bit.TRIGSEL = ${ADC_TRIGGERS[trigger]}U;`,
        `    AdcRegs.ADCSOC${soc}CTL.bit.ACQPS = ${acqps}U;`,
        '    EDIS;',
        '}',
      ]),
      'adc_init.h': lineFile([
        HEADER.trimEnd(),
        '#ifndef ADC_INIT_H',
        '#define ADC_INIT_H',
        'void Generated_Adc_Init(void);',
        '#endif',
      ]),
    };
  }

  function generateTimers(timers, sysclk) {
    if (!Object.keys(timers || {}).length) return {};
    const lines = [
      HEADER.trimEnd(),
      '#include "DSP2803x_Device.h"',
      '#include "timer_interrupt_init.h"',
      '',
    ];
    const prototypes = [];
    for (const rawName of Object.keys(timers).sort()) {
      const name = rawName.toUpperCase();
      if (name !== 'TIMER0') throw new Error(`unsupported timer ${name}`);
      const timer = timers[rawName];
      const period = Math.round(sysclk * Number(timer.period_us) / 1e6) - 1;
      if (!Number.isInteger(period) || period <= 0 || period > 0xFFFFFFFF) {
        throw new Error(`${name} period is out of range`);
      }
      const isr = timer.isr || 'cpu_timer0_isr';
      prototypes.push('void Generated_Timer0_Init(void);', `__interrupt void ${isr}(void);`);
      lines.push(
        'void Generated_Timer0_Init(void)',
        '{',
        '    CpuTimer0Regs.TCR.bit.TSS = 1U;',
        '    CpuTimer0Regs.TCR.bit.TIE = 0U;',
        '    CpuTimer0Regs.TCR.bit.TIF = 1U;',
        `    CpuTimer0Regs.PRD.all = ${period}UL;`,
        '    CpuTimer0Regs.TCR.bit.TRB = 1U;',
        '    EALLOW;',
        '    SysCtrlRegs.PCLKCR3.bit.CPUTIMER0ENCLK = 1U;',
        `    PieVectTable.TINT0 = &${isr};`,
        '    EDIS;',
        '    PieCtrlRegs.PIEIER1.bit.INTx7 = 1U;',
        '    IER |= M_INT1;',
        '    CpuTimer0Regs.TCR.bit.TIE = 1U;',
        `    CpuTimer0Regs.TCR.bit.TSS = ${timer.start_immediately === false ? 1 : 0}U;`,
        '}',
        '',
        `__interrupt void ${isr}(void)`,
        '{',
        '    PieCtrlRegs.PIEACK.bit.ACK1 = 1U;',
        '}',
        '',
      );
    }
    return {
      'timer_interrupt_init.c': lineFile(lines),
      'timer_interrupt_init.h': lineFile([
        HEADER.trimEnd(),
        '#ifndef TIMER_INTERRUPT_INIT_H',
        '#define TIMER_INTERRUPT_INIT_H',
        ...prototypes,
        '#endif',
      ]),
    };
  }

  function generateProtection(protection) {
    if (!protection) return {};
    return {
      'protection_init.c': lineFile([
        HEADER.trimEnd(),
        '#include "protection_init.h"',
        '',
        'void Generated_Protection_Init(void)',
        '{',
        '    // Project-selected hardware protection is configured in pwm_init.c.',
        '}',
      ]),
      'protection_init.h': lineFile([
        HEADER.trimEnd(),
        '#ifndef PROTECTION_INIT_H',
        '#define PROTECTION_INIT_H',
        'void Generated_Protection_Init(void);',
        '#endif',
      ]),
    };
  }

  function generateInitAll(config, pinmux, present) {
    const pwmPins = [];
    Object.values(config.pwm_modules || {}).forEach(module => {
      [module.pin_a, module.pin_b].forEach(pin => {
        const def = pin == null ? null : pdef(pinmux, pin);
        if (def) pwmPins.push(def);
      });
    });
    const includes = ['#include "generated_init_all.h"', '#include "pinmux_init.h"'];
    const calls = ['    Generated_PinMux_Init();'];
    if (present.has('system_clock_init.c')) {
      includes.push('#include "system_clock_init.h"');
      calls.unshift('    if (Generated_SystemClock_Init() != 0U) return 1U;');
    }
    if (present.has('pwm_init.c')) {
      includes.push('#include "pwm_init.h"');
      calls.push('    Generated_Pwm_Init();');
    }
    if (present.has('adc_init.c')) {
      includes.push('#include "adc_init.h"');
      calls.push('    Generated_Adc_Init();');
    }
    if (present.has('timer_interrupt_init.c')) {
      includes.push('#include "timer_interrupt_init.h"');
      calls.push('    Generated_Timer0_Init();');
    }
    if (present.has('protection_init.c')) {
      includes.push('#include "protection_init.h"');
      calls.push('    Generated_Protection_Init();');
    }
    const lines = [
      HEADER.trimEnd(),
      ...includes,
      '',
      'static void Generated_EmergencyShutdown(void)',
      '{',
      '    EALLOW;',
    ];
    if (!pwmPins.length) lines.push('    // no ePWM pins configured');
    pwmPins.forEach(def => lines.push(
      `    ${def.mux_field} = 0U;`,
      `    ${def.clr_field} = 1U;`,
      `    ${def.dir_field} = 1U;`,
      `    ${def.pud_field} = 1U;`,
    ));
    lines.push(
      '    EDIS;',
      '}',
      '',
      'Uint16 Generated_InitAll(void)',
      '{',
      '    Generated_EmergencyShutdown();',
      ...calls,
      '    return 0U;',
      '}',
    );
    return {
      'generated_init_all.c': lineFile(lines),
      'generated_init_all.h': lineFile([
        HEADER.trimEnd(),
        '#ifndef GENERATED_INIT_ALL_H',
        '#define GENERATED_INIT_ALL_H',
        '#include "DSP2803x_Device.h"',
        'Uint16 Generated_InitAll(void);',
        '#endif',
      ]),
    };
  }

  function recommendedFile(config, files, activeModule) {
    const requested = String(activeModule || '').toUpperCase();
    if (requested.startsWith('EPWM') && files['pwm_init.c']) return 'pwm_init.c';
    if (requested.startsWith('ADC') && files['adc_init.c']) return 'adc_init.c';
    if (requested.startsWith('TIMER') && files['timer_interrupt_init.c']) {
      return 'timer_interrupt_init.c';
    }
    if (requested && configuredPins(config)
      .some(pin => String(pin.function).toUpperCase() === requested)) return 'pinmux_init.c';
    if (files['pwm_init.c']) return 'pwm_init.c';
    if (files['adc_init.c']) return 'adc_init.c';
    if (files['timer_interrupt_init.c']) return 'timer_interrupt_init.c';
    return 'pinmux_init.c';
  }

  function generationReport(config, warnings) {
    return [
      '# R3.2 Static Generation Report',
      '',
      '- status: LOGIC TEST ONLY',
      '- approval: NOT APPROVED FOR POWER-STAGE ENABLE',
      `- device: ${config.device}`,
      `- package: ${config.package}`,
      `- configured pins: ${configuredPins(config).length}`,
      `- configured PWM modules: ${Object.keys(config.pwm_modules || {}).length}`,
      `- ADC configured: ${config.adc ? 'yes' : 'no'}`,
      `- timers configured: ${Object.keys(config.timers || {}).length}`,
      '- generator runtime: browser JavaScript',
      '- PWM release: explicit caller action after hardware safety checks',
      '',
      '## Warnings',
      '',
      ...(warnings.length ? warnings.map(item => `- ${item}`) : ['- none']),
      '',
    ].join('\n');
  }

  function generateProject(project, context = {}) {
    const config = JSONCore.clone(project);
    const pinmux = context.pinmux;
    const family = context.family || {};
    const validation = Checker.validateProject(config, pinmux, family);
    if (!validation.ok) {
      const error = new Error(validation.blocking.map(item => item.message).join('；'));
      error.validation = validation;
      throw error;
    }
    const sysclk = Number(config.system_clock?.sysclk_hz ||
      Number(config.system_clock?.target_mhz) * 1e6) || MAX_SYSCLK_HZ;
    const files = {};
    Object.assign(files, generatePinmux(config, pinmux));
    Object.assign(files, generateClock(config.system_clock));
    Object.assign(files, generatePwm(config, pinmux, sysclk));
    Object.assign(files, generateAdc(config.adc));
    Object.assign(files, generateTimers(config.timers || {}, sysclk));
    Object.assign(files, generateProtection(config.protection));
    Object.assign(files, generateInitAll(config, pinmux, new Set(Object.keys(files))));
    files['generated_config.json'] = JSONCore.stringify(config, 2) + '\n';
    const warnings = validation.findings
      .filter(item => item.severity === 'WARNING')
      .map(item => item.message);
    warnings.unshift('Generated sources require engineer review before any power-stage use.');
    files['generation_report.md'] = generationReport(config, warnings);
    const ordered = Object.keys(files).sort().reduce((out, name) => {
      out[name] = files[name];
      return out;
    }, {});
    return {
      files: ordered,
      recommended_file: recommendedFile(config, ordered, context.activeModule),
      active_module: context.activeModule || null,
      findings: validation.findings,
      ok: true,
    };
  }

  return {
    HEADER,
    generateProject,
    generatePinmux,
    generateClock,
    generatePwm,
    generateAdc,
    generateTimers,
  };
});
